<?php require_once __DIR__.'/../config.php';require_admin();verify_csrf();$id=(int)($_POST['id']??0);$status=$_POST['status']??'';$note=trim($_POST['admin_note']??'');$valid=['pending','reviewing','more_info','approved','declined'];if(!in_array($status,$valid,true))exit('Invalid status.');$p=db();$s=$p->prepare('SELECT * FROM applications WHERE id=?');$s->execute([$id]);$old=$s->fetch();if(!$old)exit('Not found.');$p->prepare('UPDATE applications SET status=?,admin_note=? WHERE id=?')->execute([$status,$note?:null,$id]);if($old['status']!==$status)$p->prepare('INSERT INTO application_events(application_id,event_text) VALUES(?,?)')->execute([$id,'Application status changed to '.str_replace('_',' ',$status)]);if($note!==($old['admin_note']??''))$p->prepare('INSERT INTO application_events(application_id,event_text) VALUES(?,?)')->execute([$id,'Reviewer update added']);flash('Application updated.');header("Location:view.php?id=$id");exit;